function folks(i,n,mine,dead){var h="",k,show=Math.min(n,8);for(k=0;k<show;k++){var isMe=mine&&k===0;h+='<i class="dt-p'+(isMe?" me":"")+'" style="left:'+(6+rnd(i,k,1)*66).toFixed(0)+"%;top:"+(46+rnd(i,k,2)*26).toFixed(0)+"%;animation-delay:-"+(rnd(i,k,3)*2).toFixed(2)+'s">'+(dead?"💀":isMe?"🧑‍🌾":PETS[Math.floor(rnd(i,k,4)*PETS.length)])+(isMe?"<em>我</em>":"")+"</i>";}
if(n>show)h+='<i class="dt-more">+'+(n-show)+"</i>";return h;}
